type hookedRenderer struct {
	linkifyProtocol []byte
	html.Config
}

func (r *hookedRenderer) SetOption(name renderer.OptionName, value any) {
	r.Config.SetOption(name, value)
}

// RegisterFuncs implements NodeRenderer.RegisterFuncs.
func (r *hookedRenderer) RegisterFuncs(reg renderer.NodeRendererFuncRegisterer) {
	reg.Register(ast.KindLink, r.renderLink)
	reg.Register(ast.KindAutoLink, r.renderAutoLink)
	reg.Register(ast.KindImage, r.renderImage)
	reg.Register(ast.KindHeading, r.renderHeading)
}

func (r *hookedRenderer) renderImage(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.Image)
	var lr hooks.LinkRenderer

	ctx, ok := w.(*render.Context)
	if ok {
		h := ctx.RenderContext().GetRenderer(hooks.ImageRendererType, nil)
		ok = h != nil
		if ok {
			lr = h.(hooks.LinkRenderer)
		}
	}

	if !ok {
		if !entering {
			return ast.WalkContinue, nil
		}

		_, _ = w.WriteString("<img src=\"")
		destination := n.Destination
		writeDestination := r.Unsafe
		if !writeDestination {
			dangerous := false
			if len(destination) >= 11 && bytes.Equal(bytes.ToLower(destination[:11]), []byte("data:image/")) {
				rest := destination[11:]
				safe := false
				if len(rest) >= 4 {
					kind := bytes.ToLower(rest[:4])
					if bytes.Equal(kind, []byte("png;")) || bytes.Equal(kind, []byte("gif;")) {
						safe = true
					}
				}
				if !safe && len(rest) >= 5 {
					kind := bytes.ToLower(rest[:5])
					if bytes.Equal(kind, []byte("jpeg;")) || bytes.Equal(kind, []byte("webp;")) {
						safe = true
					}
				}
				if !safe && len(rest) >= 8 && bytes.Equal(bytes.ToLower(rest[:8]), []byte("svg+xml;")) {
					safe = true
				}
				dangerous = !safe
			} else if len(destination) >= 11 && bytes.Equal(bytes.ToLower(destination[:11]), []byte("javascript:")) {
				dangerous = true
			} else if len(destination) >= 9 && bytes.Equal(bytes.ToLower(destination[:9]), []byte("vbscript:")) {
				dangerous = true
			} else if len(destination) >= 5 {
				scheme := bytes.ToLower(destination[:5])
				if bytes.Equal(scheme, []byte("file:")) || bytes.Equal(scheme, []byte("data:")) {
					dangerous = true
				}
			}
			writeDestination = !dangerous
		}
		if writeDestination {
			_, _ = w.Write(util.EscapeHTML(util.URLEscape(destination, true)))
		}
		_, _ = w.WriteString(`" alt="`)

		var altBuf bytes.Buffer
		for c := n.FirstChild(); c != nil; c = c.NextSibling() {
			if s, isString := c.(*ast.String); isString {
				if s.IsCode() {
					altBuf.Write(s.Text(source))
					continue
				}
			}
			if !c.HasChildren() {
				altBuf.Write(util.EscapeHTML(c.Text(source)))
				if t, isText := c.(*ast.Text); isText {
					if t.SoftLineBreak() {
						altBuf.WriteByte('\n')
					}
				}
				continue
			}
			for gc := c.FirstChild(); gc != nil; gc = gc.NextSibling() {
				if s, isString := gc.(*ast.String); isString {
					if s.IsCode() {
						altBuf.Write(s.Text(source))
						continue
					}
				}
				if !gc.HasChildren() {
					altBuf.Write(util.EscapeHTML(gc.Text(source)))
					if t, isText := gc.(*ast.Text); isText {
						if t.SoftLineBreak() {
							altBuf.WriteByte('\n')
						}
					}
					continue
				}
				for ggc := gc.FirstChild(); ggc != nil; ggc = ggc.NextSibling() {
					if s, isString := ggc.(*ast.String); isString {
						if s.IsCode() {
							altBuf.Write(s.Text(source))
							continue
						}
					}
					if !ggc.HasChildren() {
						altBuf.Write(util.EscapeHTML(ggc.Text(source)))
						if t, isText := ggc.(*ast.Text); isText {
							if t.SoftLineBreak() {
								altBuf.WriteByte('\n')
							}
						}
						continue
					}
					for gggc := ggc.FirstChild(); gggc != nil; gggc = gggc.NextSibling() {
						if s, isString := gggc.(*ast.String); isString {
							if s.IsCode() {
								altBuf.Write(s.Text(source))
								continue
							}
						}
						if !gggc.HasChildren() {
							altBuf.Write(util.EscapeHTML(gggc.Text(source)))
							if t, isText := gggc.(*ast.Text); isText {
								if t.SoftLineBreak() {
									altBuf.WriteByte('\n')
								}
							}
							continue
						}
						altBuf.Write(nodeToHTMLText(gggc, source))
					}
				}
			}
		}
		_, _ = w.Write(altBuf.Bytes())
		_ = w.WriteByte('"')
		if n.Title != nil {
			_, _ = w.WriteString(` title="`)
			r.Writer.Write(w, n.Title)
			_ = w.WriteByte('"')
		}
		if rawAttrs := n.Attributes(); rawAttrs != nil {
			kept := 0
			for _, attr := range rawAttrs {
				if !bytes.HasPrefix(attr.Name, []byte(internalAttrPrefix)) {
					rawAttrs[kept] = attr
					kept++
				}
			}
			filtered := rawAttrs[:kept]
			for _, attr := range filtered {
				nameLower := strings.ToLower(string(attr.Name))
				if strings.HasPrefix(nameLower, "on") {
					continue
				}
				_, _ = w.WriteString(" ")
				_, _ = w.Write(attr.Name)
				_, _ = w.WriteString(`="`)
				switch v := attr.Value.(type) {
				case []byte:
					_, _ = w.Write(util.EscapeHTML(v))
				default:
					_, _ = w.WriteString(cast.ToString(v))
				}
				_ = w.WriteByte('"')
			}
		}
		if r.XHTML {
			_, _ = w.WriteString(" />")
		} else {
			_, _ = w.WriteString(">")
		}
		return ast.WalkSkipChildren, nil
	}

	if entering {
		ctx.PushPos(ctx.Buffer.Len())
		return ast.WalkContinue, nil
	}

	pos := ctx.PopPos()
	text := ctx.Buffer.Bytes()[pos:]
	ctx.Buffer.Truncate(pos)

	var (
		isBlock bool
		ordinal int
	)
	if b, exists := n.AttributeString(images.AttrIsBlock); exists {
		if b.(bool) {
			isBlock = true
		}
	}
	if ord, exists := n.AttributeString(images.AttrOrdinal); exists {
		ordinal = ord.(int)
	}

	rawAttrs := n.Attributes()
	kept := 0
	for _, attr := range rawAttrs {
		if !bytes.HasPrefix(attr.Name, []byte(internalAttrPrefix)) {
			rawAttrs[kept] = attr
			kept++
		}
	}
	filtered := rawAttrs[:kept]

	var converted []attributes.Attribute
	for _, attr := range filtered {
		nameLower := strings.ToLower(string(attr.Name))
		if strings.HasPrefix(nameLower, "on") {
			continue
		}
		var vv any
		switch vvv := attr.Value.(type) {
		case bool, float64:
			vv = vvv
		case []any:
			var hlRanges [][2]int
			for _, l := range vvv {
				if ln, isFloat := l.(float64); isFloat {
					hlRanges = append(hlRanges, [2]int{int(ln) - 1, int(ln) - 1})
					continue
				}
				rng, isBytes := l.([]uint8)
				if !isBytes {
					continue
				}
				parts := strings.Split(string([]byte(rng)), "-")
				lhs, errL := strconv.Atoi(parts[0])
				rhs := lhs
				var errR error
				if len(parts) > 1 {
					rhs, errR = strconv.Atoi(parts[1])
				}
				if errL == nil && errR == nil {
					hlRanges = append(hlRanges, [2]int{lhs - 1, rhs - 1})
				}
			}
			vv = hlRanges
		case []byte:
			vv = string(vvv)
		default:
			panic(fmt.Sprintf("not implemented: %T", vvv))
		}
		converted = append(converted, attributes.Attribute{Name: nameLower, Value: vv})
	}

	destination := ""
	if n.Destination != nil {
		destination = string(n.Destination)
	}
	title := ""
	if n.Title != nil {
		title = string(n.Title)
	}
	plainText := string(n.Text(source))

	err := lr.RenderLink(
		ctx.RenderContext().Ctx,
		w,
		imageLinkContext{
			linkContext: linkContext{
				page:             ctx.DocumentContext().Document,
				destination:      destination,
				title:            title,
				text:             hstring.RenderedString(text),
				plainText:        plainText,
				AttributesHolder: attributes.NewHolder(converted),
			},
			ordinal: ordinal,
			isBlock: isBlock,
		},
	)

	return ast.WalkContinue, err
}

func (r *hookedRenderer) filterInternalAttributes(attrs []ast.Attribute) []ast.Attribute {
	n := 0
	for _, x := range attrs {
		if !bytes.HasPrefix(x.Name, []byte(internalAttrPrefix)) {
			attrs[n] = x
			n++
		}
	}
	return attrs[:n]
}

// Fall back to the default Goldmark render funcs. Method below borrowed from:
// https://github.com/yuin/goldmark/blob/b611cd333a492416b56aa8d94b04a67bf0096ab2/renderer/html/html.go#L404
func (r *hookedRenderer) renderImageDefault(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	if !entering {
		return ast.WalkContinue, nil
	}
	n := node.(*ast.Image)
	_, _ = w.WriteString("<img src=\"")
	if r.Unsafe || !html.IsDangerousURL(n.Destination) {
		_, _ = w.Write(util.EscapeHTML(util.URLEscape(n.Destination, true)))
	}
	_, _ = w.WriteString(`" alt="`)
	_, _ = w.Write(nodeToHTMLText(n, source))
	_ = w.WriteByte('"')
	if n.Title != nil {
		_, _ = w.WriteString(` title="`)
		r.Writer.Write(w, n.Title)
		_ = w.WriteByte('"')
	}
	if n.Attributes() != nil {
		attrs := r.filterInternalAttributes(n.Attributes())
		attributes.RenderASTAttributes(w, attrs...)
	}
	if r.XHTML {
		_, _ = w.WriteString(" />")
	} else {
		_, _ = w.WriteString(">")
	}
	return ast.WalkSkipChildren, nil
}

func (r *hookedRenderer) renderLink(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.Link)
	var lr hooks.LinkRenderer

	ctx, ok := w.(*render.Context)
	if ok {
		h := ctx.RenderContext().GetRenderer(hooks.LinkRendererType, nil)
		ok = h != nil
		if ok {
			lr = h.(hooks.LinkRenderer)
		}
	}

	if !ok {
		return r.renderLinkDefault(w, source, node, entering)
	}

	if entering {
		// Store the current pos so we can capture the rendered text.
		ctx.PushPos(ctx.Buffer.Len())
		return ast.WalkContinue, nil
	}

	pos := ctx.PopPos()
	text := ctx.Buffer.Bytes()[pos:]
	ctx.Buffer.Truncate(pos)

	err := lr.RenderLink(
		ctx.RenderContext().Ctx,
		w,
		linkContext{
			page:             ctx.DocumentContext().Document,
			destination:      string(n.Destination),
			title:            string(n.Title),
			text:             hstring.RenderedString(text),
			plainText:        string(n.Text(source)),
			AttributesHolder: attributes.Empty,
		},
	)

	return ast.WalkContinue, err
}

// Fall back to the default Goldmark render funcs. Method below borrowed from:
// https://github.com/yuin/goldmark/blob/b611cd333a492416b56aa8d94b04a67bf0096ab2/renderer/html/html.go#L404
func (r *hookedRenderer) renderLinkDefault(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.Link)
	if entering {
		_, _ = w.WriteString("<a href=\"")
		if r.Unsafe || !html.IsDangerousURL(n.Destination) {
			_, _ = w.Write(util.EscapeHTML(util.URLEscape(n.Destination, true)))
		}
		_ = w.WriteByte('"')
		if n.Title != nil {
			_, _ = w.WriteString(` title="`)
			r.Writer.Write(w, n.Title)
			_ = w.WriteByte('"')
		}
		_ = w.WriteByte('>')
	} else {
		_, _ = w.WriteString("</a>")
	}
	return ast.WalkContinue, nil
}

func (r *hookedRenderer) renderAutoLink(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	if !entering {
		return ast.WalkContinue, nil
	}

	n := node.(*ast.AutoLink)
	var lr hooks.LinkRenderer

	ctx, ok := w.(*render.Context)
	if ok {
		h := ctx.RenderContext().GetRenderer(hooks.LinkRendererType, nil)
		ok = h != nil
		if ok {
			lr = h.(hooks.LinkRenderer)
		}
	}

	if !ok {
		return r.renderAutoLinkDefault(w, source, node, entering)
	}

	url := string(r.autoLinkURL(n, source))
	label := string(n.Label(source))
	if n.AutoLinkType == ast.AutoLinkEmail && !strings.HasPrefix(strings.ToLower(url), "mailto:") {
		url = "mailto:" + url
	}

	err := lr.RenderLink(
		ctx.RenderContext().Ctx,
		w,
		linkContext{
			page:             ctx.DocumentContext().Document,
			destination:      url,
			text:             hstring.RenderedString(label),
			plainText:        label,
			AttributesHolder: attributes.Empty,
		},
	)

	return ast.WalkContinue, err
}

// Fall back to the default Goldmark render funcs. Method below borrowed from:
// https://github.com/yuin/goldmark/blob/5588d92a56fe1642791cf4aa8e9eae8227cfeecd/renderer/html/html.go#L439
func (r *hookedRenderer) renderAutoLinkDefault(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.AutoLink)
	if !entering {
		return ast.WalkContinue, nil
	}

	_, _ = w.WriteString(`<a href="`)
	url := r.autoLinkURL(n, source)
	label := n.Label(source)
	if n.AutoLinkType == ast.AutoLinkEmail && !bytes.HasPrefix(bytes.ToLower(url), []byte("mailto:")) {
		_, _ = w.WriteString("mailto:")
	}
	_, _ = w.Write(util.EscapeHTML(util.URLEscape(url, false)))
	if n.Attributes() != nil {
		_ = w.WriteByte('"')
		html.RenderAttributes(w, n, html.LinkAttributeFilter)
		_ = w.WriteByte('>')
	} else {
		_, _ = w.WriteString(`">`)
	}
	_, _ = w.Write(util.EscapeHTML(label))
	_, _ = w.WriteString(`</a>`)
	return ast.WalkContinue, nil
}

func (r *hookedRenderer) autoLinkURL(n *ast.AutoLink, source []byte) []byte {
	url := n.URL(source)
	if len(n.Protocol) > 0 && !bytes.Equal(n.Protocol, r.linkifyProtocol) {
		// The CommonMark spec says "http" is the correct protocol for links,
		// but this doesn't make much sense (the fact that they should care about the rendered output).
		// Note that n.Protocol is not set if protocol is provided by user.
		url = append(r.linkifyProtocol, url[len(n.Protocol):]...)
	}
	return url
}

func (r *hookedRenderer) renderHeading(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.Heading)
	var hr hooks.HeadingRenderer

	ctx, ok := w.(*render.Context)
	if ok {
		h := ctx.RenderContext().GetRenderer(hooks.HeadingRendererType, nil)
		ok = h != nil
		if ok {
			hr = h.(hooks.HeadingRenderer)
		}
	}

	if !ok {
		return r.renderHeadingDefault(w, source, node, entering)
	}

	if entering {
		// Store the current pos so we can capture the rendered text.
		ctx.PushPos(ctx.Buffer.Len())
		return ast.WalkContinue, nil
	}

	pos := ctx.PopPos()
	text := ctx.Buffer.Bytes()[pos:]
	ctx.Buffer.Truncate(pos)
	// All ast.Heading nodes are guaranteed to have an attribute called "id"
	// that is an array of bytes that encode a valid string.
	anchori, _ := n.AttributeString("id")
	anchor := anchori.([]byte)

	err := hr.RenderHeading(
		ctx.RenderContext().Ctx,
		w,
		headingContext{
			page:             ctx.DocumentContext().Document,
			level:            n.Level,
			anchor:           string(anchor),
			text:             hstring.RenderedString(text),
			plainText:        string(n.Text(source)),
			AttributesHolder: attributes.New(n.Attributes(), attributes.AttributesOwnerGeneral),
		},
	)

	return ast.WalkContinue, err
}

func (r *hookedRenderer) renderHeadingDefault(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.Heading)
	if entering {
		_, _ = w.WriteString("<h")
		_ = w.WriteByte("0123456"[n.Level])
		if n.Attributes() != nil {
			attributes.RenderASTAttributes(w, node.Attributes()...)
		}
		_ = w.WriteByte('>')
	} else {
		_, _ = w.WriteString("</h")
		_ = w.WriteByte("0123456"[n.Level])
		_, _ = w.WriteString(">\n")
	}
	return ast.WalkContinue, nil
}

type links struct {
	cfg goldmark_config.Config
}

// Extend implements goldmark.Extender.
func (e *links) Extend(m goldmark.Markdown) {
	m.Renderer().AddOptions(renderer.WithNodeRenderers(
		util.Prioritized(newLinkRenderer(e.cfg), 100),
	))
}

// Borrowed from Goldmark.
func nodeToHTMLText(n ast.Node, source []byte) []byte {
	var buf bytes.Buffer
	for c := n.FirstChild(); c != nil; c = c.NextSibling() {
		if s, ok := c.(*ast.String); ok && s.IsCode() {
			buf.Write(s.Text(source))
		} else if !c.HasChildren() {
			buf.Write(util.EscapeHTML(c.Text(source)))
			if t, ok := c.(*ast.Text); ok && t.SoftLineBreak() {
				buf.WriteByte('\n')
			}
		} else {
			buf.Write(nodeToHTMLText(c, source))
		}
	}
	return buf.Bytes()
}

